//! The conversations chime (book 09B §9; `master_plan_conversations.md` §4, §6): one short, soft
//! tone generated by the app itself (no sound file in the repository), written once into the data
//! folder and played with macOS's own player, so it also sounds right after launch (a web page may
//! not play sound before a click).

use std::{
    f64::consts::TAU,
    path::{Path, PathBuf},
    process::Command,
};

const RATE: u32 = 44_100;
/// Length of the tone in seconds (at most 0.6 s).
const SECONDS: f64 = 0.45;
/// The two partials (A5 and the fifth above it) and their amplitudes; their sum stays below a
/// third of full scale.
const PARTIALS: [(f64, f64); 2] = [(880.0, 0.2), (1_320.0, 0.1)];
/// Envelope: a 6 ms rise (no click), then an exponential decay.
const ATTACK_S: f64 = 0.006;
const DECAY_PER_S: f64 = 9.0;
const FILE: &str = "chime.wav";
const PLAYER: &str = "/usr/bin/afplay";

/// The chime as a 16-bit mono PCM WAV file; the same bytes on every call.
pub fn wav() -> Vec<u8> {
    let samples = (f64::from(RATE) * SECONDS) as u32;
    let data_len = samples * 2;
    let mut out = Vec::with_capacity(44 + data_len as usize);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + data_len).to_le_bytes());
    out.extend_from_slice(b"WAVE");
    out.extend_from_slice(b"fmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes()); // PCM
    out.extend_from_slice(&1u16.to_le_bytes()); // mono
    out.extend_from_slice(&RATE.to_le_bytes());
    out.extend_from_slice(&(RATE * 2).to_le_bytes()); // byte rate
    out.extend_from_slice(&2u16.to_le_bytes()); // block align
    out.extend_from_slice(&16u16.to_le_bytes()); // bits per sample
    out.extend_from_slice(b"data");
    out.extend_from_slice(&data_len.to_le_bytes());
    for n in 0..samples {
        let t = f64::from(n) / f64::from(RATE);
        let rise = (t / ATTACK_S).min(1.0);
        let envelope = rise * (-DECAY_PER_S * t).exp();
        let tone: f64 = PARTIALS
            .iter()
            .map(|(hz, amplitude)| amplitude * (TAU * hz * t).sin())
            .sum();
        let sample = (tone * envelope * f64::from(i16::MAX)).round() as i16;
        out.extend_from_slice(&sample.to_le_bytes());
    }
    out
}

/// Writes `chime.wav` into `dir` when it is absent or differs.
fn ensure_file(dir: &Path) -> std::io::Result<PathBuf> {
    let path = dir.join(FILE);
    let bytes = wav();
    if std::fs::read(&path).ok().as_deref() != Some(bytes.as_slice()) {
        std::fs::create_dir_all(dir)?;
        std::fs::write(&path, &bytes)?;
    }
    Ok(path)
}

/// Plays the chime without waiting for it: the player is started and reaped on a thread of its own,
/// so the caller (the event bridge) never blocks. Any failure is logged and swallowed.
pub fn play(dir: &Path) {
    let path = match ensure_file(dir) {
        Ok(path) => path,
        Err(error) => {
            tracing::warn!(target: "psm::conversations", %error, "chime file not written");
            return;
        }
    };
    match Command::new(PLAYER).arg(&path).spawn() {
        Ok(mut child) => {
            let _ = std::thread::Builder::new()
                .name("chime".into())
                .spawn(move || {
                    let _ = child.wait();
                });
        }
        Err(error) => tracing::warn!(target: "psm::conversations", %error, "chime not played"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn u16_at(b: &[u8], i: usize) -> u16 {
        u16::from_le_bytes([b[i], b[i + 1]])
    }
    fn u32_at(b: &[u8], i: usize) -> u32 {
        u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
    }

    /// The `data` chunk's samples.
    fn samples(b: &[u8]) -> Vec<i16> {
        b[44..]
            .as_chunks::<2>()
            .0
            .iter()
            .map(|c| i16::from_le_bytes(*c))
            .collect()
    }

    #[test]
    fn c2_c17a_a_mono_16_bit_wav_whose_chunk_sizes_match() {
        let b = wav();
        assert_eq!(&b[0..4], b"RIFF");
        assert_eq!(u32_at(&b, 4) as usize, b.len() - 8);
        assert_eq!(&b[8..12], b"WAVE");
        assert_eq!(&b[12..16], b"fmt ");
        assert_eq!(u32_at(&b, 16), 16);
        assert_eq!(u16_at(&b, 20), 1, "PCM");
        assert_eq!(u16_at(&b, 22), 1, "one channel");
        assert_eq!(u16_at(&b, 34), 16, "16 bits");
        assert_eq!(&b[36..40], b"data");
        assert_eq!(u32_at(&b, 40) as usize, b.len() - 44);
    }

    #[test]
    fn c2_c17b_short_audible_and_soft() {
        let b = wav();
        let rate = u32_at(&b, 24) as f64;
        let s = samples(&b);
        let seconds = s.len() as f64 / rate;
        assert!(seconds > 0.05 && seconds <= 0.6, "{seconds} s");
        assert!(s.iter().any(|&v| v != 0));
        let third = i32::from(i16::MAX) / 3;
        assert!(s.iter().all(|&v| i32::from(v).abs() <= third));
    }

    #[test]
    fn c2_c17c_the_same_bytes_every_time() {
        assert_eq!(wav(), wav());
    }
}
